import { CSSProperties } from 'react';

type AnyNode = {
    type: string;
    style?: CSSProperties;
    tw?: string;
    [key: string]: unknown;
};
/**
 * @deprecated Use {import("csstype").Properties} or {import("react").CSSProperties} instead
 */
type PartialStyle = CSSProperties;
type Node = ContainerNode | TextNode | ImageNode | AnyNode;
type ContainerNode = {
    type: "container";
    preset?: CSSProperties;
    style?: CSSProperties;
    children?: Node[];
    tw?: string;
};
type TextNode = {
    type: "text";
    text: string;
    preset?: CSSProperties;
    style?: CSSProperties;
    tw?: string;
};
type ImageNode = {
    type: "image";
    src: string;
    width?: number;
    height?: number;
    preset?: CSSProperties;
    style?: CSSProperties;
    tw?: string;
};

export type { AnyNode as A, ContainerNode as C, ImageNode as I, Node as N, PartialStyle as P, TextNode as T };
